import { z } from 'zod';
import { SPEECH_CONTROLS, SPEECH_PLAYBACK_FACTS, SPEECH_REQUEST_SOURCES } from '@shared/speech';

export type IpcDirection = 'invoke' | 'send' | 'event';
export type IpcWindowScope =
  | 'all'
  | 'launcher'
  | 'desktop'
  | 'settings'
  | 'pack'
  | 'result'
  | 'overlay'
  | 'live-host'
  | 'hub'
  | 'transport';
export interface IpcBridge {
  method: string;
  kind: 'invoke' | 'send' | 'on';
}
export interface IpcDescriptor {
  channel: string;
  direction: IpcDirection;
  scope: readonly IpcWindowScope[];
  group: string;
  request: z.ZodTypeAny;
  response: z.ZodTypeAny;
  bridge?: IpcBridge;
  summary: string;
}

const anyArgs = z.tuple([]).rest(z.unknown());

function descriptor(entry: Omit<IpcDescriptor, 'request' | 'response'> & { request?: z.ZodTypeAny }): IpcDescriptor {
  return { ...entry, request: entry.request ?? anyArgs, response: z.unknown() };
}

